	@Test
	void producedValueProofInvalidationRechecksProducerTrustInBothDirections() {
		assertAll(List.of(false, true).stream().map(opaque -> () -> {
			assertAll(List.of(false, true).stream().map(rootedInvalidation -> () -> {
				ExtensionElem definition = new ExtensionElem(opaque ? new HiddenExpression() : value(1), "v");
				Join root = siblingAlias(new Extension(new SingletonSet(), definition), true);
				QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(root,
						EmptyBindingSet.getInstance());
				TupleExpr initial = root.clone();
				assertThat(analysis.producesOnlyAbsentOrEqual(root, "x", VF.createLiteral(1))).isEqualTo(!opaque);
				assertThat(root).isEqualTo(initial);
				definition.setExpr(opaque ? value(1) : new HiddenExpression());
				TupleExpr changed = root.clone();
				if (rootedInvalidation) {
					analysis.invalidate(root);
				} else {
					analysis.invalidate();
				}
				assertThat(analysis.producesOnlyAbsentOrEqual(root, "x", VF.createLiteral(1))).isEqualTo(opaque);
				assertThat(root).isEqualTo(changed);
				assertThat(analysis.producesOnlyAbsentOrEqual(root, "x", VF.createLiteral(1))).isEqualTo(opaque);
				assertThat(root).isEqualTo(changed);
			}));
		}));
	}

	@Test
	void producedValueProofRejectsOpaqueOriginsImportedThroughARerootedContext() {
		assertAll(List.of(false, true).stream().map(chain -> () -> {
			Join root = opaqueSiblingAlias(chain);
			TupleExpr snapshot = root.clone();
			QueryAlgebraBindingAnalysis outer = QueryAlgebraBindingAnalysis.withBindingValues(root,
					EmptyBindingSet.getInstance());
			var imported = outer.contextAt(root.getRightArg());
			assertThat(imported.fixedValues()).containsEntry("v", VF.createLiteral(1));
			QueryAlgebraBindingAnalysis inner = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(
					root.getRightArg(), imported, Set.of());
			assertThat(inner.producesOnlyAbsentOrEqual(root.getRightArg(), "x", VF.createLiteral(1))).isFalse();
			assertThat(root).isEqualTo(snapshot);
			assertThat(inner.producesOnlyAbsentOrEqual(root.getRightArg(), "x", VF.createLiteral(1))).isFalse();
			assertThat(root).isEqualTo(snapshot);
		}));
	}

	private static Join opaqueSiblingAlias(boolean chain) {
		return siblingAlias(new Extension(new SingletonSet(), new ExtensionElem(new HiddenExpression(), "v")), chain);
	}

	private static Join siblingAlias(TupleExpr producer, boolean chain) {
		Extension consumer = chain
				? new Extension(new SingletonSet(), new ExtensionElem(Var.of("v"), "copy"),
						new ExtensionElem(Var.of("copy"), "x"))
				: new Extension(new SingletonSet(), new ExtensionElem(Var.of("v"), "x"));
		return new Join(producer, consumer);
	}

	private static void assertProducedProof(TupleExpr expression, boolean expected) {
		assertProducedProof(expression, EmptyBindingSet.getInstance(), expected);
	}

	private static void assertProducedProof(TupleExpr expression, BindingSet incoming, boolean expected) {
		assertProducedProof(expression, incoming, VF.createLiteral(1), expected);
	}

	private static void assertProducedProof(TupleExpr expression, BindingSet incoming, Value expectedValue,
			boolean expected) {
		assertProducedProof(expression, expression, incoming, expectedValue, expected);
	}

	private static void assertProducedProof(TupleExpr root, TupleExpr expression, BindingSet incoming,
			Value expectedValue,
			boolean expected) {
		TupleExpr snapshot = root.clone();
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(root, incoming);
		assertThat(analysis.producesOnlyAbsentOrEqual(expression, "x", expectedValue)).isEqualTo(expected);
		assertThat(root).isEqualTo(snapshot);
		assertThat(analysis.producesOnlyAbsentOrEqual(expression, "x", expectedValue)).isEqualTo(expected);
		assertThat(root).isEqualTo(snapshot);
	}

	private static BindingSetAssignment nullableValues(String name, Integer... values) {
		List<BindingSet> rows = new ArrayList<>();
		for (Integer value : values) {
			MapBindingSet row = new MapBindingSet();
			if (value != null) {
				row.addBinding(name, VF.createLiteral(value));
			}
			rows.add(row);
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of(name));
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static void assertProof(TupleExpr expression, boolean expected) {
		TupleExpr snapshot = expression.clone();
		assertThat(QueryAlgebraBindingAnalysis.provesUnusedIncomingValue(expression, "x")).isEqualTo(expected);
		assertThat(expression).isEqualTo(snapshot);
		assertThat(QueryAlgebraBindingAnalysis.provesUnusedIncomingValue(expression, "x")).isEqualTo(expected);
		assertThat(expression).isEqualTo(snapshot);
	}

	private static Projection project(TupleExpr argument, ProjectionElem element) {
		return new Projection(argument, new ProjectionElemList(element));
	}

	private static BindingSetAssignment values(int value) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("x"));
		values.setBindingSets(List.of(row(value)));
		return values;
	}

	private static MapBindingSet row(int value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("x", VF.createLiteral(value));
		return row;
	}

	private static ValueConstant value(int value) {
		return new ValueConstant(VF.createLiteral(value));
	}

	private static final class HiddenExpression extends ValueConstant {
		HiddenExpression() {
			super(VF.createLiteral(1));
		}
	}
